-- 栈应用：递归调用的活动记录与逐层返回。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '递归与调用栈','调用栈保存活动记录，最深层调用先返回；递归深度决定额外栈空间。',course.id,parent.id,'cs408-recursion-call-stack','AISTU',1,'REVIEWED',7,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-recursion-call-stack' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-recursion-call-stack',1,'REVIEWED','递归与调用栈',JSON_OBJECT('summary','函数调用创建活动记录并压入调用栈，记录参数、局部变量、返回地址和执行状态。递归继续时上一层暂停在调用点；基例结束后最内层先返回，随后逐层恢复。递归深度决定额外栈空间，缺少有效基例会持续增长。','steps',JSON_ARRAY('每次调用创建一条活动记录并压栈','递归调用让当前层暂停在调用点','基例停止继续压入新活动记录','最内层活动记录先弹出并返回结果','调用者逐层恢复，递归深度决定栈空间'),'visualization',JSON_OBJECT('kind','FACTORIAL_CALL_STACK','version',1,'startValue',4),'prerequisite',JSON_OBJECT('contentKey','cs408-stack-lifo','title','栈的 LIFO 语义与基本操作','description','先掌握最后压入的活动记录最先弹出。')),JSON_OBJECT('id','recursion-call-stack-v1','prompt','递归到达基例后，哪个调用最先恢复执行？','options',JSON_ARRAY(JSON_OBJECT('id','INNER_RETURNS_FIRST','text','最内层、最后压入调用栈的调用'),JSON_OBJECT('id','OUTER_RETURNS_FIRST','text','最外层、最先开始的调用')),'correctOptionId','INNER_RETURNS_FIRST','correctExplanation','正确：调用栈遵循 LIFO，基例所在的最内层活动记录先弹出。','incorrectExplanation','不正确：外层调用仍停在调用点，必须等待内层返回结果。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-recursion-call-stack' AND existing.content_version=1 WHERE point.content_key='cs408-recursion-call-stack' AND existing.id IS NULL;
